samples.sql:
SELECT CDSCode
FROM frpm
WHERE `Enrollment (K-12)` + `Enrollment (Ages 5-17)` > 500;

SELECT 
    (SELECT COUNT(*) FROM schools WHERE MailState = 'CA' AND County = 'Colusa') * 1.0 /
    (SELECT COUNT(*) FROM schools WHERE MailState = 'CA' AND County = 'Humboldt') AS ratio;

SELECT Website
FROM schools
WHERE Virtual = 'P' AND Charter = 1 AND County = 'San Joaquin';

SELECT School, City, AdmFName1 || ' ' || AdmLName1, AdmFName2 || ' ' || AdmLName2, AdmFName3 || ' ' || AdmLName3
FROM schools
WHERE Charter = 1 AND CharterNum = '00D2';

SELECT COUNT(*) 
FROM schools 
WHERE MailCity = 'Hickman' AND CharterNum = '00D4';

SELECT SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan
WHERE amount < 100000;

SELECT A3, A2
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT 
    (SELECT SUM(A16) FROM district WHERE A3 = 'north Bohemia') -
    (SELECT SUM(A16) FROM district WHERE A3 = 'east Bohemia') AS difference;

SELECT ROUND(SUM(element = 'h') * 100.0 / COUNT(atom_id), 4) AS percent
FROM atom
WHERE molecule_id = 'TR206';

SELECT COUNT(bond_id)
FROM connected
WHERE atom_id LIKE 'TR%_19' OR atom_id2 LIKE 'TR%_19';

SELECT COUNT(*) 
FROM atom 
WHERE molecule_id IN (
    SELECT molecule_id FROM bond WHERE bond_type = '#'
) 
AND molecule_id IN (
    SELECT molecule_id FROM atom WHERE element IN ('p', 'br')
);

SELECT T1.element FROM atom AS T1 JOIN connected AS T2 ON T1.atom_id = T2.atom_id WHERE T2.bond_id = 'TR000_1_2'
UNION
SELECT T1.element FROM atom AS T1 JOIN connected AS T2 ON T1.atom_id = T2.atom_id2 WHERE T2.bond_id = 'TR000_1_2';

SELECT 
  ROUND(
    CAST(
      (SELECT COUNT(*) FROM molecule m 
       WHERE EXISTS (
         SELECT 1 FROM bond b 
         WHERE b.molecule_id = m.molecule_id 
           AND b.bond_type = '#'
       )
      ) AS FLOAT
    ) / 
    (SELECT COUNT(*) FROM molecule) * 100, 
    2
  ) AS percentage;

SELECT SUM(bond_type = ' = ') / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT COUNT(*) FROM (
  SELECT atom_id FROM connected WHERE bond_id = 'TR001_3_4'
  UNION
  SELECT atom_id2 FROM connected WHERE bond_id = 'TR001_3_4'
);

SELECT COUNT(*)
FROM molecule
WHERE label = '-'
  AND molecule_id IN (
    SELECT molecule_id FROM bond WHERE bond_type = '#'
  );

SELECT 
    (SELECT COUNT(*) FROM foreign_data fd JOIN cards c ON fd.uuid = c.uuid WHERE fd.language = 'French' AND c.isStorySpotlight = 1) * 100.0 / 
    (SELECT COUNT(*) FROM cards WHERE isStorySpotlight = 1) AS percentage;

SELECT COUNT(*)
FROM cards
WHERE borderColor = 'black' AND availability = 'mtgo';

SELECT CAST(SUM(isOnlineOnly) AS FLOAT) * 100.0 / COUNT(id) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

SELECT SUM(CASE WHEN convertedManaCost = 10 THEN 1 ELSE 0 END) * 100.0 / COUNT(*)
FROM cards
WHERE name = 'Abyssal Horror';

SELECT COUNT(st.translation)
FROM set_translations st
WHERE st.setCode IN (
    SELECT c.setCode FROM cards c WHERE c.name = 'Angel of Mercy'
);

SELECT 
    (SELECT COUNT(*) FROM posts WHERE OwnerUserId = 24) * 1.0 / 
    (SELECT COUNT(*) FROM votes WHERE UserId = 24);

SELECT ViewCount
FROM posts
WHERE Title = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

SELECT Text
FROM comments
WHERE Score = 17;

SELECT COUNT(*)
FROM comments
WHERE UserId = 13;

SELECT RelatedPostId AS related_post, (SELECT ViewCount FROM posts WHERE Id = 61217) AS popularity
FROM postLinks
WHERE PostId = 61217;

SELECT Text
FROM comments
WHERE CreationDate = '2010-07-19 19:25:47.0';

SELECT 
    (SELECT COUNT(DISTINCT UserId) FROM badges WHERE Name = 'Teacher') * 100.0 / 
    (SELECT COUNT(Id) FROM users) AS percentage;

SELECT Text
FROM comments
WHERE CreationDate = '2010-07-19 19:37:33.0';

SELECT COUNT(*)
FROM votes
WHERE strftime('%Y', CreationDate) = '2010';

SELECT
  (SELECT SUM(ViewCount) FROM posts JOIN users ON posts.OwnerUserId = users.Id WHERE users.DisplayName = 'Mornington') -
  (SELECT SUM(ViewCount) FROM posts JOIN users ON posts.OwnerUserId = users.Id WHERE users.DisplayName = 'Amos');

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(DISTINCT PostId)
FROM votes
WHERE strftime('%Y', CreationDate) = '2011' AND BountyAmount = 50;

SELECT COUNT(*)
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(*)
FROM posts
WHERE ViewCount > 35000 AND CommentCount = 0;

SELECT COUNT(*)
FROM tags
WHERE Id < 15 AND Count <= 20;

SELECT CAST(SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) AS FLOAT) * 100.0 / COUNT(s.id) 
FROM superhero s 
LEFT JOIN colour c ON s.eye_colour_id = c.id;

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT CAST(SUM(CASE WHEN gender_id = 2 THEN 1 ELSE 0 END) AS FLOAT) / COUNT(*) * 100.0
FROM superhero
WHERE alignment_id = 2;

SELECT COUNT(*)
FROM superhero
WHERE full_name LIKE 'John%';

SELECT CAST(COUNT(CASE WHEN time IS NOT NULL AND time != '' THEN driverId END) AS FLOAT) / COUNT(driverId) * 100 AS percentage
FROM results
WHERE raceId IN (SELECT raceId FROM races WHERE date = '1983-07-16');

SELECT COUNT(*)
FROM circuits
WHERE location = 'Adelaide' AND country = 'Australia';

SELECT COUNT(*)
FROM drivers
WHERE nationality = 'British' AND strftime('%Y', dob) > '1980';

SELECT raceId
FROM races
WHERE year = 2009;

SELECT location, country, lat, lng
FROM circuits
WHERE name = 'Hungaroring';

SELECT AVG(c) FROM (
    SELECT COUNT(*) AS c
    FROM races
    WHERE date BETWEEN '2000-01-01' AND '2010-12-31'
    GROUP BY year
);

SELECT COUNT(DISTINCT player_api_id)
FROM Player_Attributes
WHERE overall_rating >= 60 AND overall_rating < 65 AND defensive_work_rate = 'low';

SELECT player_name
FROM Player
WHERE (strftime('%Y', 'now', 'localtime') - strftime('%Y', birthday)) - (strftime('%m-%d', 'now', 'localtime') < strftime('%m-%d', birthday)) > 34;

SELECT CAST(SUM(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 ELSE 0 END) AS FLOAT) / COUNT(pa.id) * 100 AS percentage
FROM Player_Attributes pa
JOIN Player p ON pa.player_api_id = p.player_api_id;

SELECT CAST(COUNT(CASE WHEN strftime('%Y', Birthday) > '1930' THEN ID END) AS FLOAT) / COUNT(ID) * 100
FROM Patient
WHERE SEX = 'F';

SELECT SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT 
    (SELECT COUNT(ID) FROM Patient WHERE Diagnosis = 'SLE' AND Admission = '+') * 1.0 /
    (SELECT COUNT(ID) FROM Patient WHERE Diagnosis = 'SLE' AND Admission = '-') AS ratio;

SELECT SUM(Laboratory.UA <= 8.0 AND Patient.SEX = 'M') * 1.0 / SUM(Laboratory.UA <= 6.5 AND Patient.SEX = 'F') AS ratio
FROM Patient
JOIN Laboratory ON Patient.ID = Laboratory.ID;

SELECT CAST(SUM(Diagnosis = 'BEHCET') AS FLOAT) / COUNT(*) * 100 
FROM Patient 
WHERE SEX = 'M' AND strftime('%Y', `First Date`) = '1981';

SELECT COUNT(DISTINCT T1.ID)
FROM Laboratory AS T1
WHERE strftime('%Y', T1.Date) = '1997' AND (T1.TP <= 6 OR T1.TP >= 8.5);

SELECT SUM(SEX = 'F') * 100.0 / COUNT(SEX) AS percentage
FROM Patient
WHERE strftime('%Y', Birthday) = '1980' AND Diagnosis = 'RA';

SELECT COUNT(*)
FROM Patient p
WHERE p.ID IN (
    SELECT ID FROM Laboratory WHERE `T-BIL` >= 2.0
)
AND p.ID IN (
    SELECT ID FROM Examination WHERE `ANA Pattern` LIKE '%P%'
);

SELECT 
    (SELECT SUM(b.spent) FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE substr(e.event_date, 1, 4) = '2019') -
    (SELECT SUM(b.spent) FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE substr(e.event_date, 1, 4) = '2020') AS difference;

SELECT DISTINCT department
FROM major
WHERE college = 'College of Humanities and Social Sciences';

SELECT COUNT(event_id)
FROM event
WHERE type = 'Meeting' AND strftime('%Y', event_date) = '2020';

SELECT 1.0 * SUM(major_name = 'Finance') / SUM(major_name = 'Physics')
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT first_name || ' ' || last_name AS full_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(spent) / COUNT(spent)
FROM budget
WHERE category = 'Food' AND event_status = 'Closed';

SELECT SUM(type = 'Community Service') * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(member.position = 'Member' AND major.major_name = 'Business') * 100.0 / COUNT(member.member_id) AS percentage
FROM member
LEFT JOIN major ON member.link_to_major = major.major_id;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT
  (SELECT COUNT(*) FROM gasstations WHERE Country = 'CZE' AND Segment = 'discount') -
  (SELECT COUNT(*) FROM gasstations WHERE Country = 'SVK' AND Segment = 'discount') AS difference;

SELECT
  (SELECT Consumption FROM yearmonth WHERE CustomerID = 7 AND Date = '201304') -
  (SELECT Consumption FROM yearmonth WHERE CustomerID = 5 AND Date = '201304') AS consumption_difference;

SELECT 
  (SELECT COUNT(*) FROM customers WHERE Segment = 'SME' AND Currency = 'CZK') -
  (SELECT COUNT(*) FROM customers WHERE Segment = 'SME' AND Currency = 'EUR') AS more_SMEs;

SELECT CAST(SUM(CASE WHEN Currency = 'Euro' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)
FROM customers
WHERE Segment = 'KAM';

SELECT 
    (SELECT SUM(Amount * Price) FROM transactions_1k WHERE CustomerID = 38508) AS total_spent_at_gas_stations,
    (SELECT Consumption FROM yearmonth WHERE CustomerID = 38508 AND Date = '201201') AS spent_in_january_2012;
